#include <bits/stdc++.h>
using namespace std;

const int maxn = 510;

int m, n, mod;

int add_mod (int x, int y) {return (x + y) % mod;}
int sub_mod (int x, int y) {return x - y < 0 ? x - y + mod : x - y;}
int mul_mod (int x, int y) {return (long long) x * y % mod;}
int fac[maxn], inv[maxn], invfac[maxn];

void compute_factorials(int n)
{
    fac[0] = inv[1] = fac[1] = invfac[0] = invfac[1] = 1;
    for (int i = 2; i <= n; i++) inv[i] = mul_mod((mod - mod / i), inv[mod % i]);
    for (int i = 2; i <= n; i++) {fac[i] = mul_mod(fac[i - 1], i); invfac[i] = mul_mod(invfac[i - 1], inv[i]);}
}

int choose(int n, int m) {
    if (n < m || m < 0) return 0;
    return mul_mod(mul_mod(fac[n], invfac[m]), invfac[n - m]);
}

int perm(int n, int m) {
    return choose(n + m - 1, m - 1);
}

int f[maxn], g[maxn], s[maxn];
int ff[maxn][maxn], gg[maxn][maxn];

int main()
{
    scanf("%d %d %d", &n, &m, &mod);
    compute_factorials(500);
    for (int i = 1; i <= n; i++) s[i] = add_mod(s[i - 1], i);
    f[0] = 1; f[1] = 2;
    g[0] = 0; g[1] = 0;
    for (int i = 2; i <= n; i++)
    {
        for (int j = 0; j < i; j++)
        {
            int temp = mul_mod(choose(i - 1, j), mul_mod(f[j], f[i - 1 - j]));
            f[i] = add_mod(f[i], mul_mod(temp, i + 1));
            g[i] = add_mod(g[i], mul_mod(temp, s[j] + s[i - 1 - j]));
            temp = mul_mod(add_mod(mul_mod(g[j], f[i - 1 - j]), mul_mod(g[i - 1 - j], f[j])), i + 1);
            g[i] = add_mod(g[i], mul_mod(temp, choose(i - 1, j)));
        }
    }
    ff[0][0] = 1; gg[0][0] = 0;
    for (int i = 0; i <= m; i++)
        for (int j = 0; j <= m; j++)
        {
            if (!ff[i][j]) continue;
            for (int k = 1; k + j <= m; k++)
            {
                ff[i + 1][j + k] = add_mod(ff[i + 1][j + k], mul_mod(mul_mod(ff[i][j], f[k]), choose(j + k, k)));
                gg[i + 1][j + k] = add_mod(gg[i + 1][j + k], mul_mod(add_mod(mul_mod(gg[i][j], f[k]), mul_mod(ff[i][j], g[k])), choose(j + k, k)));
            }
        }
    int ans = 0;
    for (int i = 1; i <= m; i++)
        if (n + 1 - m >= i)
            ans = add_mod(ans, mul_mod(gg[i][m], perm(n + 1 - m - i, i + 1)));
    printf("%d\n", ans);
    return 0;
}
